## Why This Is Asked
Tests the ability to combine fetch, Service Workers, and WebSockets with a practical offline-first UI. Emphasizes conflict resolution via last-writer-wins and a lightweight diff/apply strategy.

## Key Concepts
- Offline-first fetch with Service Worker caching
- WebSocket reconnection strategy with exponential backoff
- Minimal DOM diff/patch engine for efficient row updates
- Offline edit queue with replay on reconnect and per-item last-writer-wins conflict resolution

## Code Example
```javascript
// Fetch wrapper sketch
function createFetchWrapper(baseUrl) {
  return async function fetchWrapper(endpoint, options = {}) {
    const cache = await caches.open('inventory-v1');
    const cached = await cache.match(baseUrl + endpoint);

    if (cached && !options.forceRefresh) {
      return cached;
    }

    const response = await fetch(baseUrl + endpoint, options);
    if (response.ok) {
      cache.put(baseUrl + endpoint, response.clone());
    }
    return response;
  };
}

// WebSocket wrapper sketch
function createWsWrapper(url, handlers) {
  let ws = null;
  let retryDelay = 1000;
  const editQueue = [];

  function connect() {
    ws = new WebSocket(url);

    ws.onopen = () => {
      retryDelay = 1000;
      replayQueue();
      handlers.onOpen?.();
    };

    ws.onmessage = (e) => handlers.onMessage(JSON.parse(e.data));

    ws.onclose = () => {
      setTimeout(connect, retryDelay);
      retryDelay = Math.min(retryDelay * 2, 30000);
    };
  }

  function replayQueue() {
    while (editQueue.length) {
      ws.send(JSON.stringify(editQueue.shift()));
    }
  }

  connect();

  return {
    send: (data) => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.send(JSON.stringify(data));
      } else {
        editQueue.push(data);
      }
    }
  };
}

// Diff applier sketch
function applyDiff(currentItems, updates) {
  const itemMap = new Map(currentItems.map(item => [item.id, item]));

  for (const update of updates) {
    const existing = itemMap.get(update.id);
    if (!existing || update.ts > existing.ts) {
      itemMap.set(update.id, update);
    }
  }

  return Array.from(itemMap.values()).sort((a, b) => b.ts - a.ts);
}
```

## Why This Is Asked
Tests understanding of combining Context with a small Redux-like store, debounce patterns, and memoized rendering for performance.

## Key Concepts
- useReducer + Context for lightweight global store
- Debounce with useEffect
- Memoized selectors with useMemo
- React.memo for granular re-render control
- Cleanup on unmount and dependency changes

## Code Example
```javascript
// store.js
import React from 'react'

export const AppConfigContext = React.createContext({ apiEndpoint: '/api', debounce: 300 })

const initialState = { query: '', results: [] }

function reducer(state, action) {
  switch (action.type) {
    case 'SET_QUERY':
      return { ...state, query: action.payload }
    case 'SET_RESULTS':
      return { ...state, results: action.payload }
    default:
      return state
  }
}

export function useStore() {
  const [state, dispatch] = React.useReducer(reducer, initialState)
  const actions = React.useMemo(() => ({
    setQuery: (q) => dispatch({ type: 'SET_QUERY', payload: q }),
    setResults: (r) => dispatch({ type: 'SET_RESULTS', payload: r })
  }), [])
  return { state, actions }
}
```

```javascript
// DebouncedSearchInput.js
import React from 'react'
export function DebouncedSearchInput({ value, onChange, delay = 300 }) {
  const [local, setLocal] = React.useState(value)
  React.useEffect(() => {
    const id = setTimeout(() => onChange(local), delay)
    return () => clearTimeout(id)
  }, [local, delay, onChange])
  React.useEffect(() => setLocal(value), [value])
  return <input value={local} onChange={(e) => setLocal(e.target.value)} />
}
```

